def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    my_c = sum(1 for a in my if a == 'C')
    opp_def = n - sum(1 for a in opp if a == 'C')
    my_def = n - my_c

    last_my = my[-1]
    last_opp = opp[-1]

    if n == 99:
        return 'D'

    retal = 0
    my_def_events = 0
    for i in range(n-1):
        if my[i] == 'D':
            my_def_events += 1
            if opp[i+1] == 'D':
                retal += 1

    if my_def_events < 3:
        target_coop = 0.85
    else:
        retal_rate = retal / my_def_events
        if retal_rate > 0.5:
            target_coop = 0.84
        elif retal_rate > 0.2:
            target_coop = 0.80
        else:
            target_coop = 0.75

    if last_opp == 'D':
        recent_my_def = sum(1 for a in my[-3:] if a == 'D')
        if recent_my_def > 0:
            if opp_def <= max(1, n // 10):
                return 'C'
            if last_my == 'D' and opp_def <= n // 2:
                return 'C'
            return 'D'
        else:
            if opp_def <= max(1, n // 15):
                return 'C'
            return 'D'

    if last_my == 'D':
        return 'C'

    my_c_rate = my_c / n
    if my_c_rate > target_coop:
        return 'D'

    return 'C'
